<?php
/**
 * Project: Teznevise WordPress Theme
 * Author: MAZ//ID (Maziyar)
 * Brand: MΛZ — https://github.com/maziyarid/M-Z
 *
 * Ensures screenshot.png exists for Appearance → Themes preview.
 *
 * @package Teznevise
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function teznevise_ensure_screenshot() {
	$path = TEZNEVISE_DIR . '/screenshot.png';
	if ( file_exists( $path ) && filesize( $path ) > 500 ) {
		return;
	}
	$b64 = '';
	// phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions.obfuscation_base64_decode,WordPress.WP.AlternativeFunctions.file_system_operations_file_put_contents
	file_put_contents( $path, base64_decode( $b64 ) );
}
add_action( 'after_setup_theme', 'teznevise_ensure_screenshot', 5 );
